 let fixture=fixture();let original=&fixture["original"];let full=grant(&original["grant"]);let zero=grant(&original["closeZeroGrant"]);let close=grant(&original["closeFundedGrant"]);let policy=&fixture["cancellation"];let pattern=policy["bytePattern"].as_array().unwrap();let bytes=(0..policy["byteCount"].as_u64().unwrap()as usize).map(|index|pattern[index%pattern.len()].as_u64().unwrap()as u8).collect::<Vec<_>>();let snapshot=super::BinarySnapshot{schema:original["canonicalSchema"].as_str().unwrap().into(),bytes};
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{for checkpoint in policy["checkpoints"].as_array().unwrap(){let checkpoint=checkpoint.as_str().unwrap();let total=snapshot.bytes.len();let after=match checkpoint{"first"=>0,"interior"=>total/2,"final"=>total,_=>unreachable!()};let armed=Cell::new(false);let reached=Cell::new(false);let restored=Cell::new(false);let mut callback=|event:NativeEncodeProgress|{if !armed.get(){restored.set(event.completed==17&&event.total==17);return true}let stop=event.total==total&&event.completed>=after;reached.set(reached.get()||stop);!stop};let mut recipient=NativeEncodeRetirementRecipient::new();let mut native=semio_framework_value::NativeEncodeControl::new(original["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();native.begin_stage(17).unwrap();native.advance(17).unwrap();armed.set(true);let mut owner=NativeSnapshotEncodeOwner::new(&mut native,full);let mut sql_callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_callback,Default::default());let(result,born,released)=observe(||snapshot.encode_sqlite_snapshot_native(encoding,&mut control,&mut owner));let progress=owner.progress();drop(owner);assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert!(reached.get());assert_eq!(released,0);assert_eq!(born,progress.retained_capacity_bytes);assert!(native.has_retirement_owner());armed.set(false);native.checkpoint().unwrap();assert!(restored.get());let(_,zero_born,zero_release)=observe(||native.close_retirement_recipient(zero).unwrap());assert_eq!((zero_born,zero_release),(0,0));assert!(native.has_retirement_owner());let mut total_release=0;let mut total_birth=born;while native.has_retirement_owner(){let(step,close_born,close_release)=observe(||native.close_retirement_recipient(close).unwrap());assert_eq!(close_born,step.progress().retained_capacity_bytes);assert_eq!(close_release,step.progress().released_bytes);total_release+=close_release;total_birth+=close_born;}assert_eq!(total_release,total_birth);eprintln!("[DEBUG] Original Binary {encoding:?}/{checkpoint} output cancellation actual born{born}/released0, zero close0/0 and funded release{total_release}");}}
