#[test]
fn binary_original_receiving_required_pack_retains_every_cancelled_backing_and_raw_carrier(){
 use semio_framework_os_kernel::{ArtifactPackReceiving,NativeSnapshotDecodeOwner};
 use semio_framework_value::{native_decoding::NativeDecodeRetirementRecipient,ControlledRetirement,RetainedCloneStep,ValueRefusalKind};
 let fixture=fixture();let original=&fixture["original"];let full=grant(&original["grant"]);let close=grant(&original["closeFundedGrant"]);let zero=grant(&original["closeZeroGrant"]);let policy=&fixture["cancellation"];let pattern=policy["bytePattern"].as_array().unwrap();let bytes=(0..policy["byteCount"].as_u64().unwrap()as usize).map(|index|pattern[index%pattern.len()].as_u64().unwrap()as u8).collect::<Vec<_>>();let wire=bytes.as_ptr();let mut canceled=0;
 for cut in 0..24{
  let enabled=Cell::new(true);let turns=Cell::new(0usize);let mut callback=|_|{let turn=turns.get();turns.set(turn+1);!enabled.get()||turn<cut};let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(original["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();let mut owner=NativeSnapshotDecodeOwner::new(&mut native,full);
  let(result,born,released)=observe(||super::BinarySnapshot::receive_pack(&bytes,&mut owner));let progress=owner.progress();assert_eq!(born,progress.retained_capacity_bytes);assert_eq!(released,progress.released_bytes);drop(owner);enabled.set(false);assert_eq!(wire,bytes.as_ptr());let mut output=match result{Ok(output)=>{assert_eq!(output.bytes,bytes);assert_eq!(output.schema,crate::STDIO_BINARY_DOCUMENT_SCHEMA);Some(output)},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.retained_progress(),progress);canceled+=1;None}};
  let mut extra_born=0;let mut extra_released=0;
  if native.has_retirement_owner(){let(step,b,r)=observe(||native.close_retirement_recipient(zero).unwrap());assert_eq!((b,r),(0,0));assert_eq!(step.progress(),Default::default());assert!(native.has_retirement_owner());}
  for _ in 0..4096{if !native.has_retirement_owner(){break}let(step,b,r)=observe(||native.close_retirement_recipient(close).unwrap());assert_eq!(b,step.progress().retained_capacity_bytes);assert_eq!(r,step.progress().released_bytes);extra_born+=b;extra_released+=r;}assert!(!native.has_retirement_owner());
  let mut retirement=ControlledRetirement::new(output.take()).unwrap();for _ in 0..4096{if retirement.terminal_is_empty(){break}let(step,b,r)=observe(||retirement.step(close).unwrap());assert_eq!(b,step.progress().retained_capacity_bytes);assert_eq!(r,step.progress().released_bytes);extra_born+=b;extra_released+=r;if matches!(step,RetainedCloneStep::Complete(_)){break}}assert!(retirement.terminal_is_empty());assert_eq!(born+extra_born,released+extra_released);
  eprintln!("[DEBUG] Original required Binary raw receiver cut{cut} actual born{born}/released{released}, retained original wire, fixed-policy cleanup{extra_born}/{extra_released}");
 }
 assert!(canceled>0);
}
